<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <meta name="description" content="Transparent pricing for Cedar & Sky Wellness programs. Flexible plans, community-rate seats, and no-pressure enrollment." />
  <meta name="theme-color" content="#16352a" />
  <title>Pricing | {{BUSINESS_NAME}} — Clear, flexible plans</title>
  <style>
    :root{
      --forest-900:#0e2a20;--forest-800:#16352a;--forest-700:#1e4638;--forest-500:#2f6b4e;--moss-400:#5c8f6f;--sky-300:#9fd5eb;--sky-200:#cbeaf5;--snow-50:#f7faf9;--sand-100:#ebe7e1;--clay-300:#b9836a;--text-900:#142019;--text-700:#284236;--muted-600:#5a6c64;--shadow:0 10px 30px rgba(4,28,22,.15);--radius-l:20px;--radius-m:14px;--radius-s:10px;--max:1160px
    }
    *{box-sizing:border-box}
    html{scroll-behavior:smooth}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Ubuntu,Cantarell,Noto Sans,sans-serif;color:var(--text-900);background:linear-gradient(180deg,var(--snow-50),#fff)}
    .container{max-width:var(--max);margin:0 auto;padding:0 20px}
    .skip-link{position:absolute;left:-9999px;top:auto;width:1px;height:1px;overflow:hidden}
    .skip-link:focus{position:fixed;left:20px;top:20px;width:auto;height:auto;padding:10px 14px;background:#fff;border-radius:8px;box-shadow:var(--shadow);z-index:10000}

    header.site-header{position:sticky;top:0;z-index:999;background:rgba(247,250,249,.7);backdrop-filter:saturate(140%) blur(10px);border-bottom:1px solid rgba(22,53,42,.08)}
    .nav{display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:72px}
    .brand{display:flex;align-items:center;gap:12px;text-decoration:none}
    .brand-mark{width:36px;height:36px;border-radius:12px;background:radial-gradient(120px 80px at 30% 30%, var(--sky-200), transparent 60%),linear-gradient(135deg,var(--forest-700),var(--forest-800));box-shadow:inset 0 0 0 2px rgba(255,255,255,.3)}
    .brand-name{font-weight:700;color:var(--forest-900);letter-spacing:.2px}
    nav ul{display:flex;gap:16px;list-style:none;margin:0;padding:0}
    nav a{color:var(--text-700);text-decoration:none;padding:10px 12px;border-radius:10px}
    nav a[aria-current="page"], nav a:hover{background:rgba(46,93,59,.08);color:var(--forest-800)}
    .cta{display:inline-flex;align-items:center;gap:10px;background:linear-gradient(180deg,var(--forest-700),var(--forest-800));color:#fff !important;padding:10px 14px;border-radius:12px;box-shadow:var(--shadow);border:1px solid rgba(255,255,255,.15)}
    .cta .dot{width:8px;height:8px;background:var(--sky-300);border-radius:99px}
    .menu-toggle{display:none;background:#fff;border:1px solid rgba(22,53,42,.15);border-radius:12px;padding:10px 12px}
    .menu-toggle[aria-expanded="true"]{background:var(--snow-50)}

    .hero{position:relative;isolation:isolate}
    .hero .bg{position:absolute;inset:0;z-index:-1;background:
      radial-gradient(70% 60% at 85% -10%, rgba(159,213,235,.35), transparent 60%),
      radial-gradient(70% 60% at -10% 20%, rgba(47,107,78,.12), transparent 60%),
      linear-gradient(180deg,#fff, var(--snow-50))}
    .hero-inner{display:grid;grid-template-columns:1.1fr .9fr;gap:36px;padding:72px 0}
    .eyebrow{display:inline-flex;align-items:center;gap:8px;color:var(--moss-400);font-weight:600;background:rgba(159,213,235,.25);border:1px solid rgba(159,213,235,.5);padding:6px 10px;border-radius:999px}
    .hero h1{font-size:clamp(28px,4.6vw,48px);line-height:1.1;margin:14px 0 10px;color:var(--forest-900)}
    .hero p{color:var(--muted-600);font-size:1.05rem;max-width:56ch}
    .actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:18px}
    .btn{display:inline-flex;align-items:center;gap:10px;padding:12px 16px;border-radius:14px;border:1px solid transparent;text-decoration:none;font-weight:600}
    .btn-primary{background:linear-gradient(180deg,var(--forest-700),var(--forest-800));color:#fff;border-color:rgba(255,255,255,.12)}
    .btn-secondary{background:#fff;color:var(--forest-800);border-color:rgba(22,53,42,.15)}
    .hero-visual img{width:100%;height:auto;border-radius:18px;border:1px solid rgba(22,53,42,.08);box-shadow:var(--shadow);background:#fff}

    .section{padding:56px 0}
    .section .hd{display:flex;align-items:end;justify-content:space-between;gap:16px;margin-bottom:20px}
    .section h2{margin:0;color:var(--forest-900);font-size:clamp(22px,3.2vw,34px)}
    .muted{color:var(--muted-600)}

    .toggle-wrap{display:inline-flex;align-items:center;gap:10px;background:#fff;border:1px solid rgba(22,53,42,.12);border-radius:999px;padding:6px}
    .toggle-wrap button{all:unset;padding:8px 12px;border-radius:999px;cursor:pointer}
    .toggle-wrap button[aria-pressed="true"]{background:rgba(46,93,59,.1);font-weight:700;color:var(--forest-800)}

    .plans{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:16px}
    .card{background:#fff;border:1px solid rgba(22,53,42,.08);border-radius:20px;padding:20px;box-shadow:var(--shadow);display:flex;flex-direction:column;gap:12px}
    .label{display:inline-flex;align-items:center;gap:8px;font-size:.85rem;color:var(--forest-700);background:rgba(46,93,59,.08);padding:6px 10px;border-radius:999px;width:max-content}
    .price{font-weight:800;color:var(--forest-800)}
    .sub{font-size:.92rem;color:var(--muted-600);margin:0}
    .features{margin:0;padding:0 0 0 20px;color:var(--text-700)}

    .note{background:linear-gradient(180deg,#fff,var(--snow-50));border:1px solid rgba(22,53,42,.12);border-radius:18px;padding:14px;margin-top:10px}

    .benefits{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
    .benefit{background:#fff;border:1px solid rgba(22,53,42,.08);border-radius:var(--radius-m);padding:18px;display:grid;grid-template-columns:auto 1fr;gap:12px;align-items:start;box-shadow:0 3px 16px rgba(4,28,22,.05)}
    .icon{width:38px;height:38px;border-radius:12px;display:grid;place-items:center;background:linear-gradient(180deg,var(--sky-200),#fff);border:1px solid rgba(22,53,42,.08)}

    .testimonials{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
    .quote{background:#fff;border:1px solid rgba(22,53,42,.08);border-radius:18px;padding:18px;box-shadow:0 6px 22px rgba(4,28,22,.06)}
    .quote header{display:flex;align-items:center;gap:12px;margin-bottom:8px}
    .quote img{width:42px;height:42px;border-radius:50%;border:1px solid rgba(22,53,42,.12)}
    .stars{color:#f0b429;font-size:14px}

    .faq{display:grid;grid-template-columns:1fr 1fr;gap:18px}
    .faq-item{background:#fff;border:1px solid rgba(22,53,42,.08);border-radius:16px;padding:12px}
    .faq-item button{all:unset;display:flex;align-items:center;justify-content:space-between;gap:16px;width:100%;padding:10px;cursor:pointer}
    .faq-q{font-weight:700;color:var(--forest-900)}
    .faq-a{padding:0 10px 10px 10px;color:var(--muted-600)}
    .chev{transition:transform .2s ease}

    .lead{position:relative;border:1px solid rgba(22,53,42,.12);background:linear-gradient(180deg,#fff,var(--snow-50));border-radius:22px;padding:22px;display:grid;grid-template-columns:1.2fr .8fr;gap:14px;box-shadow:var(--shadow)}
    .lead form{display:flex;flex-wrap:wrap;gap:10px}
    .field{display:grid;gap:6px;flex:1 1 220px}
    .field input{border:1px solid rgba(22,53,42,.18);border-radius:12px;padding:12px 14px}
    .error{color:#b5473f;font-size:.9rem;display:none}
    .success{display:none;color:var(--forest-700);font-weight:600}

    .cta-band{background:linear-gradient(180deg,var(--forest-700),var(--forest-800));border-radius:22px;padding:24px;color:#fff;display:grid;grid-template-columns:1fr auto;align-items:center;gap:16px}
    .cta-band .btn{background:#fff;color:var(--forest-800)}

    footer{margin-top:56px;padding:36px 0;border-top:1px solid rgba(22,53,42,.1)}
    .footer-grid{display:grid;grid-template-columns:2fr 1fr 1fr;gap:18px}
    address{font-style:normal;color:var(--muted-600)}
    .small{font-size:.92rem;color:var(--muted-600)}

    @media (max-width: 960px){
      .hero-inner{grid-template-columns:1fr;gap:18px;padding:42px 0}
      .plans{grid-template-columns:1fr}
      .benefits{grid-template-columns:1fr 1fr}
      .testimonials{grid-template-columns:1fr 1fr}
      .faq{grid-template-columns:1fr}
      .lead{grid-template-columns:1fr}
      .cta-band{grid-template-columns:1fr}
      .footer-grid{grid-template-columns:1fr 1fr}
    }
    @media (max-width: 720px){
      .menu-toggle{display:inline-flex}
      nav .links{position:fixed;inset:72px 16px auto 16px;background:#fff;border:1px solid rgba(22,53,42,.12);border-radius:16px;box-shadow:var(--shadow);padding:8px;display:none;flex-direction:column}
      nav .links a{padding:12px;border-radius:10px}
      nav .links[data-open="true"]{display:flex}
      nav .desktop-only{display:none}
      .benefits{grid-template-columns:1fr}
      .testimonials{grid-template-columns:1fr}
      .footer-grid{grid-template-columns:1fr}
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to content</a>
  <header class="site-header">
    <div class="container nav">
      <a class="brand" href="index.html" aria-label="Home">
        <span class="brand-mark" aria-hidden="true"></span>
        <span class="brand-name">{{BUSINESS_NAME}}</span>
      </a>
      <button class="menu-toggle" aria-expanded="false" aria-controls="menu">Menu</button>
      <nav aria-label="Main navigation">
        <ul id="menu" class="links">
          <li><a href="index.html">Home</a></li>
          <li><a href="about.html">About</a></li>
          <li><a href="services.html">Services</a></li>
          <li><a href="programs.html">Programs</a></li>
          <li><a aria-current="page" href="pricing.html">Pricing</a></li>
          <li><a href="testimonials.html">Testimonials</a></li>
          <li class="desktop-only"><a class="cta" href="{{PRIMARY_CTA_URL}}"><span class="dot"></span>{{PRIMARY_CTA_LABEL}}</a></li>
        </ul>
      </nav>
    </div>
  </header>

  <main id="main">
    <section class="hero">
      <div class="bg pattern" aria-hidden="true" style="background-image:url('assets/img/pattern.svg');background-size:320px auto"></div>
      <div class="container hero-inner">
        <div>
          <span class="eyebrow">Transparent & flexible</span>
          <h1>{{BUSINESS_NAME}}</h1>
          <p class="muted">{{TAGLINE}} — Clear plans with pay‑monthly and pay‑in‑full options. Community-rate seats are reserved each quarter because access matters.</p>
          <div class="actions">
            <a class="btn btn-primary" href="#plans">Compare plans</a>
            <a class="btn btn-secondary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          </div>
        </div>
        <div class="hero-visual">
          <img src="assets/img/hero.svg" alt="Pricing illustration with forest, sky, and snow palette" />
        </div>
      </div>
    </section>

    <section id="plans" class="section">
      <div class="container">
        <div class="hd">
          <h2>Plans & pricing</h2>
          <div class="toggle-wrap" role="group" aria-label="Billing toggle">
            <button id="mToggle" aria-pressed="true">Monthly</button>
            <button id="yToggle" aria-pressed="false">Pay in full • Save 10%</button>
          </div>
        </div>
        <div class="plans">
          <article id="evergreen" class="card" aria-labelledby="t1-title">
            <span class="label">Foundations • 6 weeks</span>
            <h3 id="t1-title">Evergreen Basics</h3>
            <div class="price" data-monthly>$320/mo</div>
            <div class="price" data-upfront hidden>$864 total (save $96)</div>
            <p class="sub">Weekly 60-min sessions, habit map, breathwork audio, and weekday messaging.</p>
            <ul class="features">
              <li>Gentle habit stack across sleep, light, and movement</li>
              <li>Personalized morning & wind‑down rituals</li>
              <li>Asynchronous check‑ins Tue–Thu</li>
            </ul>
            <div class="note">Best for: busy professionals seeking calm energy with minimal time load.</div>
            <div class="actions">
              <a class="btn btn-secondary" href="programs.html#tiers">Program details</a>
              <a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">Enroll • {{PRIMARY_CTA_LABEL}}</a>
            </div>
          </article>
          <article id="moss" class="card" aria-labelledby="t2-title">
            <span class="label">Deep Dive • 12 weeks</span>
            <h3 id="t2-title">Moss & Morning Light</h3>
            <div class="price" data-monthly>$640/mo</div>
            <div class="price" data-upfront hidden>$1,728 total (save $192)</div>
            <p class="sub">Weekly 75‑min sessions, custom protocol, integration weeks, and daily support.</p>
            <ul class="features">
              <li>Nutrition, movement, and recovery strategy</li>
              <li>Daily micro‑practices and reflection prompts</li>
              <li>Guided nature breaks (audio)</li>
            </ul>
            <div class="note">Best for: meaningful change across energy, stress patterns, and sleep.</div>
            <div class="actions">
              <a class="btn btn-secondary" href="programs.html#tiers">Program details</a>
              <a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">Enroll • {{PRIMARY_CTA_LABEL}}</a>
            </div>
          </article>
          <article id="skybound" class="card" aria-labelledby="t3-title">
            <span class="label">Intensive • 8 weeks</span>
            <h3 id="t3-title">Skybound Reset</h3>
            <div class="price" data-monthly>$980/mo</div>
            <div class="price" data-upfront hidden>$1,764 total (save $196)</div>
            <p class="sub">Two 50‑min sessions weekly, on‑call text window, and lab‑informed strategy.</p>
            <ul class="features">
              <li>White‑glove calendar concierge</li>
              <li>Recovery toolkit and breath stack</li>
              <li>Executive‑specific boundary and focus coaching</li>
            </ul>
            <div class="note">Best for: leaders needing rapid, compassionate restoration with structure.</div>
            <div class="actions">
              <a class="btn btn-secondary" href="programs.html#tiers">Program details</a>
              <a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">Enroll • {{PRIMARY_CTA_LABEL}}</a>
            </div>
          </article>
        </div>
      </div>
    </section>

    <section class="section">
      <div class="container">
        <div class="hd">
          <h2>What’s included across all plans</h2>
          <p class="muted">Premium experience without the pressure.</p>
        </div>
        <div class="benefits" role="list">
          <article class="benefit" role="listitem">
            <div class="icon" aria-hidden="true">📔</div>
            <div>
              <h3 style="margin:0 0 6px 0">Personalized Ritual Workbook</h3>
              <p class="muted" style="margin:0">A living document capturing your habits, adjustments, and reflections.</p>
            </div>
          </article>
          <article class="benefit" role="listitem">
            <div class="icon" aria-hidden="true">🎧</div>
            <div>
              <h3 style="margin:0 0 6px 0">Guided Audios</h3>
              <p class="muted" style="margin:0">Breathwork, sunlight rituals, and 5‑minute nature breaks in the Cedar & Sky palette.</p>
            </div>
          </article>
          <article class="benefit" role="listitem">
            <div class="icon" aria-hidden="true">🧡</div>
            <div>
              <h3 style="margin:0 0 6px 0">Compassionate Accountability</h3>
              <p class="muted" style="margin:0">You’ll feel supported, not pushed—progress at a human pace.</p>
            </div>
          </article>
        </div>
      </div>
    </section>

    <section class="section pattern" aria-labelledby="voices-title" style="background-image:url('assets/img/pattern.svg');background-size:320px auto">
      <div class="container">
        <div class="hd">
          <h2 id="voices-title">Client voices</h2>
          <p class="muted">Proof lives in calmer mornings and steadier days.</p>
        </div>
        <div class="testimonials">
          <figure class="quote">
            <header>
              <img src="assets/img/avatar.svg" alt="Client portrait" />
              <figcaption>
                <strong>Devon T.</strong><div class="small">Product • Boise</div>
              </figcaption>
              <div class="stars" aria-label="5 out of 5">★★★★★</div>
            </header>
            <blockquote cite="#">
              “Transparent pricing, no pressure, and the value was obvious by week two.”
            </blockquote>
          </figure>
          <figure class="quote">
            <header>
              <img src="assets/img/avatar.svg" alt="Client portrait" />
              <figcaption>
                <strong>Nalini P.</strong><div class="small">Physician • San Diego</div>
              </figcaption>
              <div class="stars" aria-label="5 out of 5">★★★★★</div>
            </header>
            <blockquote cite="#">
              “Daily support kept me consistent without feeling watched. I finally sleep well.”
            </blockquote>
          </figure>
          <figure class="quote">
            <header>
              <img src="assets/img/avatar.svg" alt="Client portrait" />
              <figcaption>
                <strong>Evan K.</strong><div class="small">Ops • Minneapolis</div>
              </figcaption>
              <div class="stars" aria-label="5 out of 5">★★★★★</div>
            </header>
            <blockquote cite="#">
              “Pay‑in‑full savings plus the workbook and audios—worth every penny.”
            </blockquote>
          </figure>
        </div>
      </div>
    </section>

    <section class="section" aria-labelledby="faq-title">
      <div class="container">
        <div class="hd">
          <h2 id="faq-title">Pricing FAQs</h2>
          <p class="muted">Clarity first. Always.</p>
        </div>
        <div class="faq" data-accordion>
          <div class="faq-item">
            <button aria-expanded="false" aria-controls="fq1"><span class="faq-q">Do you accept HSA/FSA?</span><span class="chev" aria-hidden="true">▾</span></button>
            <div id="fq1" class="faq-a" hidden>
              Many clients use HSA/FSA for coaching under wellness or prevention; check your plan. We provide itemized receipts upon request.
            </div>
          </div>
          <div class="faq-item">
            <button aria-expanded="false" aria-controls="fq2"><span class="faq-q">Are there payment plans?</span><span class="chev" aria-hidden="true">▾</span></button>
            <div id="fq2" class="faq-a" hidden>
              Yes—monthly billing is standard. Pay‑in‑full saves 10% and reserves your preferred start date.
            </div>
          </div>
          <div class="faq-item">
            <button aria-expanded="false" aria-controls="fq3"><span class="faq-q">What’s your refund policy?</span><span class="chev" aria-hidden="true">▾</span></button>
            <div id="fq3" class="faq-a" hidden>
              If you attend sessions and complete agreed practices for two weeks without progress, we’ll pause and prorate remaining sessions—no hassle.
