          <div class="faq-item">
            <button aria-expanded="false" aria-controls="fq4"><span class="faq-q">Do you offer sliding‑scale seats?</span><span class="chev" aria-hidden="true">▾</span></button>
            <div id="fq4" class="faq-a" hidden>
              We reserve a limited number each quarter for clients in caregiving, education, or transition. Email {{EMAIL}} for current availability.
            </div>
          </div>
        </div>
      </div>
    </section>

    <section class="section">
      <div class="container">
        <div class="lead">
          <div>
            <h2 style="margin:0 0 8px 0">Free 3‑Day Calm Energy Reset</h2>
            <p class="muted" style="margin:0 0 12px 0">Try our approach before you enroll—no spam, just gentle science and nature‑led practices.</p>
            <form id="lead-form" novalidate>
              <div class="field">
                <label for="lead-name">Name</label>
                <input id="lead-name" name="name" type="text" autocomplete="name" placeholder="Your name" />
                <div class="error" id="err-name">Please enter your name.</div>
              </div>
              <div class="field">
                <label for="lead-email">Email</label>
                <input id="lead-email" name="email" type="email" autocomplete="email" placeholder="you@example.com" required />
                <div class="error" id="err-email">Please enter a valid email.</div>
              </div>
              <button class="btn btn-primary" type="submit">Get the guide</button>
              <div class="success" id="lead-success" role="status" aria-live="polite">Check your inbox—your guide is on the way.</div>
            </form>
          </div>
          <img src="assets/img/pattern.svg" alt="Decorative cedar & sky pattern" style="border-radius:16px;border:1px solid rgba(22,53,42,.1);width:100%;height:auto" />
        </div>
      </div>
    </section>

    <section class="section">
      <div class="container">
        <div class="cta-band">
          <div>
