  <script>
    // Mobile nav toggle
    (function(){
      const btn = document.querySelector('.menu-toggle');
      const links = document.getElementById('menu');
      if(!btn || !links) return;
      const close = () => { btn.setAttribute('aria-expanded','false'); links.dataset.open = 'false'; };
      const open = () => { btn.setAttribute('aria-expanded','true'); links.dataset.open = 'true'; };
      btn.addEventListener('click',()=>{ (btn.getAttribute('aria-expanded')==='true'?close:open)(); });
      links.addEventListener('click',e=>{ if(e.target.closest('a')) close(); });
      document.addEventListener('keydown',e=>{ if(e.key==='Escape') close(); });
    })();

    // Smooth scroll
    document.addEventListener('click',function(e){
      const a = e.target.closest('a[href^="#"]');
      if(!a || a.getAttribute('href')==='#') return;
      const id = a.getAttribute('href').slice(1);
      const el = document.getElementById(id);
      if(el){ e.preventDefault(); el.scrollIntoView({behavior:'smooth',block:'start'}); el.focus?.({preventScroll:true}); }
    });

    // Billing toggle
    (function(){
      const m = document.getElementById('mToggle');
      const y = document.getElementById('yToggle');
      const showMonthly = ()=>{
        document.querySelectorAll('[data-monthly]').forEach(n=>n.hidden=false);
        document.querySelectorAll('[data-upfront]').forEach(n=>n.hidden=true);
        m.setAttribute('aria-pressed','true'); y.setAttribute('aria-pressed','false');
      };
      const showUpfront = ()=>{
        document.querySelectorAll('[data-monthly]').forEach(n=>n.hidden=true);
        document.querySelectorAll('[data-upfront]').forEach(n=>n.hidden=false);
        m.setAttribute('aria-pressed','false'); y.setAttribute('aria-pressed','true');
      };
      m?.addEventListener('click',showMonthly); y?.addEventListener('click',showUpfront);
    })();

    // Accordion FAQ
    (function(){
      const root = document.querySelector('[data-accordion]');
      if(!root) return;
      const items = root.querySelectorAll('.faq-item');
      items.forEach(item=>{
        const btn = item.querySelector('button');
        const panel = item.querySelector('.faq-a');
        const chev = item.querySelector('.chev');
        btn.addEventListener('click',()=>{
          const openNow = btn.getAttribute('aria-expanded')==='true';
          items.forEach(i=>{
            const b=i.querySelector('button'); const p=i.querySelector('.faq-a'); const c=i.querySelector('.chev');
            b.setAttribute('aria-expanded','false'); p.hidden=true; if(c) c.style.transform='rotate(0deg)';
          });
          if(!openNow){ btn.setAttribute('aria-expanded','true'); panel.hidden=false; chev.style.transform='rotate(180deg)'; }
        });
      });
    })();

    // Lead form validation hints
    (function(){
      const f = document.getElementById('lead-form');
      if(!f) return;
      const name = f.querySelector('#lead-name');
      const email = f.querySelector('#lead-email');
      const errName = f.querySelector('#err-name');
      const errEmail = f.querySelector('#err-email');
      const success = f.querySelector('#lead-success');
      const emailValid = (v)=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v);
      const show = (el)=>{ el.style.display='block'; };
      const hide = (el)=>{ el.style.display='none'; };
      const mark = (input, bad)=>{ input.setAttribute('aria-invalid', bad?'true':'false'); input.style.outline = bad?'2px solid #b5473f':'none'; };
      f.addEventListener('submit', e=>{
        let ok = true;
        if(name && name.value.trim().length<2){ ok=false; show(errName); mark(name,true); }
        else { hide(errName); mark(name,false); }
        if(!emailValid(email.value)){ ok=false; show(errEmail); mark(email,true); }
        else { hide(errEmail); mark(email,false); }
        if(!ok){ e.preventDefault(); success.style.display='none'; }
        else { e.preventDefault(); success.style.display='block'; f.reset(); }
      });
      [name,email].forEach(i=> i&&i.addEventListener('input',()=>{ hide(i===name?errName:errEmail); mark(i,false); }));
    })();
  </script>
</body>
</html>"}
